B.UZ=new A.a_(B.y,["Nova City. Uma cidade onde humanos e rob\xf4s vivem juntos, em paz... tudo gra\xe7as \xe0 energia do N\xfacleo Nova.","Nova City. A city where humans and robots live together in peace... all thanks to the energy of the Nova Core.","Nova City. Una ciudad donde humanos y robots viven juntos, en paz... todo gracias a la energ\xeda del N\xfacleo Nova."],t.w)
B.aiy=new A.e6(null,B.UZ,null)
B.UX=new A.a_(B.y,["Olha s\xf3 esse c\xe9u! Dia perfeito pra treinar. Nada pode estragar isso... n\xe9, Zek?","Look at that sky! A perfect day to train. Nothing can ruin this... right, Zek?","\xa1Mira ese cielo! Un d\xeda perfecto para entrenar. Nada puede arruinarlo... \xbfverdad, Zek?"],t.w)
B.aip=new A.e6("kael",B.UX,"happy")
B.UQ=new A.a_(B.y,["Ai, n\xe3o! Por que voc\xea foi falar isso, Kael? Toda vez que algu\xe9m fala isso, d\xe1 tudo errado!","Oh, no! Why did you say that, Kael? Every time someone says that, everything goes wrong!","\xa1Ay, no! \xbfPor qu\xe9 dijiste eso, Kael? \xa1Cada vez que alguien lo dice, todo sale mal!"],t.w)
B.aiz=new A.e6("zek",B.UQ,"scared")
B.UG=new A.a_(B.y,["Relaxa, Zek! O que poderia acontecer?","Relax, Zek! What could possibly happen?","\xa1Tranquilo, Zek! \xbfQu\xe9 podr\xeda pasar?"],t.w)
B.ain=new A.e6("kael",B.UG,"happy")
B.RW=s([B.aiy,B.aip,B.aiz,B.ain],t.tG)
B.aiF=new A.lB("intro_1.jpg",1.05,1.18,B.dK,B.eJ,B.RW)
B.Ve=new A.a_(B.y,["Gente... olhem pra cima! O sol... est\xe1 sumindo!","Guys... look up! The sun... is disappearing!","Chicos... \xa1miren arriba! El sol... \xa1est\xe1 desapareciendo!"],t.w)
B.ais=new A.e6("luna",B.Ve,"scared")
B.V8=new A.a_(B.y,["Que coisa gigante \xe9 aquela?! Parece um castelo voando!","What is that giant thing?! It looks like a flying castle!","\xbf\xa1Qu\xe9 es esa cosa gigante!? \xa1Parece un castillo volando!"],t.w)
B.ait=new A.e6("mira",B.V8,"shocked")
B.UO=new A.a_(B.y,["Durante o eclipse, uma fortaleza sombria surgiu no c\xe9u: a Cidadela Eclipse.","During the eclipse, a dark fortress rose in the sky: the Eclipse Citadel.","Durante el eclipse, una fortaleza oscura apareci\xf3 en el cielo: la Ciudadela Eclipse."],t.w)
B.aix=new A.e6(null,B.UO,null)
